const prefKey='abap-reading-v1';
let pref={text:16,code:16,wrap:false,focus:false};
try{const d=JSON.parse(localStorage.getItem(prefKey)||'{}');pref={text:Math.max(15,Math.min(20,Number(d.text)||16)),code:Math.max(14,Math.min(22,Number(localStorage.getItem('abap-code-font-size'))||Number(d.code)||16)),wrap:d.wrap===true,focus:d.focus===true};}catch{}
let deps={},queued=false,returnFocus=null;
function apply(){document.documentElement.style.setProperty('--reading-text-size',pref.text+'px');document.documentElement.style.setProperty('--code-size',pref.code+'px');document.body.classList.toggle('code-wrap',pref.wrap);document.body.classList.toggle('reading-focus',pref.focus);try{localStorage.setItem(prefKey,JSON.stringify(pref));localStorage.setItem('abap-code-font-size',String(pref.code));}catch{}sync();document.dispatchEvent(new CustomEvent('reading-change'));}
function sync(){const text=document.querySelector('#reading-text-output'),code=document.querySelector('#reading-code-output'),wrap=document.querySelector('#reading-wrap'),focus=document.querySelector('[data-reading-focus]');if(text&&text.textContent!==pref.text+'px')text.textContent=pref.text+'px';if(code&&code.textContent!==pref.code+'px')code.textContent=pref.code+'px';if(wrap)wrap.checked=pref.wrap;if(focus){const label=pref.focus?'집중 읽기 해제':'집중 읽기';if(focus.textContent!==label)focus.textContent=label;focus.setAttribute('aria-pressed',String(pref.focus));}const syntax=document.querySelector('#syntax-font-size');if(syntax&&syntax.textContent!==pref.code+'px')syntax.textContent=pref.code+'px';}
export const getCodeSize=()=>pref.code;
export function setCodeSize(value){pref.code=Math.max(14,Math.min(22,Number(value)||16));apply();}
export function readingControls(){return `<details class="reading-settings"><summary>가독성 설정</summary><div class="reading-popover"><strong>글자 크기·줄바꿈 설정</strong><div><span>본문 크기 <output id="reading-text-output">${pref.text}px</output></span><button data-reading-text="-1" aria-label="본문 글자 작게">A−</button><button data-reading-text="1" aria-label="본문 글자 크게">A+</button></div><div><span>코드 크기 <output id="reading-code-output">${pref.code}px</output></span><button data-reading-code="-1" aria-label="코드 글자 작게">A−</button><button data-reading-code="1" aria-label="코드 글자 크게">A+</button></div><label><input id="reading-wrap" type="checkbox" ${pref.wrap?'checked':''}> 긴 코드 자동 줄바꿈</label><button class="button secondary" data-reading-focus aria-pressed="${pref.focus}">${pref.focus?'집중 읽기 해제':'집중 읽기'}</button><button class="text-link" data-reading-reset>기본 보기로 돌아가기</button></div></details>`;}
function rawCode(pre){const lines=[...pre.querySelectorAll('.code-line')];return lines.length?lines.map(l=>l.lastElementChild?.textContent||'').join('\n'):pre.textContent;}
function enhance(){queued=false;document.querySelectorAll('pre.code-view,pre.abap-code').forEach(pre=>{if(pre.dataset.readingReady||pre.closest('#code-focus'))return;pre.dataset.readingReady='true';const bar=document.createElement('div');bar.className='code-reading-bar';const button=document.createElement('button');button.type='button';button.dataset.codeExpand='';button.textContent='⤢ 크게 보기';button.setAttribute('aria-label',(pre.getAttribute('aria-label')||'코드')+' 크게 보기');bar.append(button);pre.before(bar);});sync();}
function closeCode(){const dialog=document.querySelector('#code-focus');if(dialog){dialog.close();dialog.remove();returnFocus?.focus?.();}}
export function bindReading(d){deps=d;apply();document.addEventListener('click',async e=>{const b=e.target.closest('button');const details=document.querySelector('.reading-settings');if(details&&!e.target.closest('.reading-settings'))details.open=false;if(!b)return;if(b.dataset.readingText){pref.text=Math.max(15,Math.min(20,pref.text+Number(b.dataset.readingText)));apply();}if(b.dataset.readingCode)setCodeSize(pref.code+Number(b.dataset.readingCode));if(b.hasAttribute('data-reading-focus')){pref.focus=!pref.focus;apply();}if(b.hasAttribute('data-reading-reset')){pref={text:16,code:16,wrap:false,focus:false};apply();}if(b.hasAttribute('data-code-expand')){closeCode();returnFocus=b;const pre=b.parentElement.nextElementSibling;if(!pre?.matches('pre.code-view,pre.abap-code'))return;const dialog=document.createElement('dialog');dialog.id='code-focus';dialog.className='code-focus';dialog.setAttribute('aria-label','코드 크게 보기');dialog.innerHTML='<header><strong>코드 크게 보기</strong><div><button data-code-focus-copy>코드 복사</button><button data-code-focus-close aria-label="확대 코드 닫기">닫기 ✕</button></div></header>';const clone=pre.cloneNode(true);clone.classList.add('code-view');dialog.append(clone);dialog.dataset.code=rawCode(pre);document.body.append(dialog);dialog.showModal();dialog.addEventListener('cancel',e=>{e.preventDefault();closeCode();});dialog.querySelector('[data-code-focus-close]').focus();return;}if(b.hasAttribute('data-code-focus-close'))closeCode();if(b.hasAttribute('data-code-focus-copy'))await deps.copy(document.querySelector('#code-focus').dataset.code,'확대해서 본 코드');if(b.hasAttribute('data-to-top'))window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});document.addEventListener('change',e=>{if(e.target.id==='reading-wrap'){pref.wrap=e.target.checked;apply();}});new MutationObserver(()=>{if(!queued){queued=true;queueMicrotask(enhance);}}).observe(document.querySelector('#app'),{childList:true,subtree:true});new MutationObserver(()=>{if(!queued){queued=true;queueMicrotask(enhance);}}).observe(document.querySelector('#overlay'),{childList:true,subtree:true});document.addEventListener('reading-change',sync);enhance();}
